#include "utils/class_names.hpp"

#include <yaml-cpp/yaml.h>

#include <stdexcept>

std::vector<std::string> loadClassNames(const std::string& path, int numClasses) {
    YAML::Node node = YAML::LoadFile(path);  // throws YAML::BadFile if missing

    if (!node.IsMap())
        throw std::runtime_error("The class mapping YAML " + path +
                                 " is not a map. Ensure that it was correctly generated by "
                                 "export_rfdetr_pretrained_classes.py.");

    std::vector<std::string> classNames(numClasses);

    for (int i = 0; i < numClasses; ++i) {
        classNames[i] = "class_" + std::to_string(i);
    }

    for (const auto& kv : node) {
        int idx = kv.first.as<int>();
        std::string name = kv.second.as<std::string>();
        if (idx >= numClasses || idx < 0) {
            throw std::runtime_error("Class name " + name + " in the mapping YAML " + path +
                                     " has index " + std::to_string(idx) +
                                     ", which is out of bounds for the number of classes: " +
                                     std::to_string(numClasses));
        }
        classNames[idx] = name;
    }

    return classNames;
}
